package cl.skinspad.reporte.soporte;
import java.util.*;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import com.fasterxml.jackson.databind.JsonNode;import static cl.skinspad.reporte.soporte.SoporteDtos.*;import static cl.skinspad.reporte.soporte.EstadosSoporte.*;
@RestController @RequestMapping("/api") @RequiredArgsConstructor public class ReporteController {
 private final ReporteService service;private final ReporteRepository reportes;private final SoporteIdentidad identidad;private final SoporteCuotas cuotas;private final SoporteJson json;private final ReporteAcciones acciones;private final SoporteRegistro registro;private final SoporteContexto contexto;private final SoporteCatalogoClient catalogo;private final SoporteUsuarioClient usuarios;private final PrecioService precios;
 @PostMapping("/reportes") @ResponseStatus(org.springframework.http.HttpStatus.CREATED) public ReporteVista crear(@RequestHeader(value="Authorization",required=false)String auth,@RequestBody JsonNode b){var a=identidad.validar(auth,false);SoporteIdentidad.cliente(a);var r=json.leer(b,NuevoReporte.class);service.preparar(r,a);cuotas.preparar(a.id());return service.crear(r,a);}
 @GetMapping("/reportes/mis-reportes") public List<ReporteVista> mios(@RequestHeader(value="Authorization",required=false)String auth){return service.mios(identidad.validar(auth,false));}
 @GetMapping("/reportes/{id}") public ReporteVista obtener(@PathVariable Long id,@RequestHeader(value="Authorization",required=false)String auth){return service.obtener(id,identidad.validar(auth,false));}
 @PostMapping("/admin/reportes/{id}/asignar") public ReporteVista asignar(@PathVariable Long id,@RequestHeader(value="Authorization",required=false)String auth,@RequestBody JsonNode b){var a=identidad.validar(auth,true);return service.asignar(id,json.leer(b,Asignacion.class),a);}
 @PostMapping("/admin/reportes/{id}/resolver") public ReporteVista resolver(@PathVariable Long id,@RequestHeader(value="Authorization",required=false)String auth,@RequestBody JsonNode b){var a=identidad.validar(auth,true);service.solicitar(id,json.leer(b,Resolver.class),a);acciones.ejecutar(id);return service.obtener(id,a);}
 @PostMapping("/admin/reportes/{id}/reintentar") public ReporteVista reintentar(@PathVariable Long id,@RequestHeader(value="Authorization",required=false)String auth){var a=identidad.validar(auth,true);acciones.ejecutar(id);return service.obtener(id,a);}
 @GetMapping("/admin/reportes/{id}/eventos") public List<EventoVista> eventos(@PathVariable Long id,@RequestHeader(value="Authorization",required=false)String auth){service.acceso(id,identidad.validar(auth,true));return registro.historial("REPORTE",id);}
 @GetMapping("/admin/reportes/{id}") public ContextoReporte contexto(@PathVariable Long id,@RequestHeader(value="Authorization",required=false)String auth){var a=identidad.validar(auth,true);var r=service.acceso(id,a);Object objetivo;AlertaVista precio=null;var permitidas=new ArrayList<Accion>(List.of(Accion.SIN_ACCION,Accion.ADVERTENCIA,Accion.USUARIO_SUSPENDIDO));
  try{if(r.getTipoObjetivo()==Objetivo.PUBLICACION){var p=catalogo.obtener(Long.valueOf(r.getObjetivoId()));objetivo=p;if(!p.reservada()&&Set.of("ACTIVO","PENDIENTE_APROBACION").contains(p.estado()))permitidas.add(Accion.PUBLICACION_DESPUBLICADA);try{precio=precios.contexto(p.id());}catch(RuntimeException e){precio=new AlertaVista(p.id(),0,p.nombre(),"NO_DISPONIBLE",p.precio(),null,0,"No se pudo consultar comparables; reintenta");}}
   else if(r.getTipoObjetivo()==Objetivo.USUARIO){objetivo=usuarios.obtener(r.getObjetivoId());}
   else{var o=contexto.operacion(Long.valueOf(r.getObjetivoId()));objetivo=Map.of("id",o.id(),"estado",o.estado(),"productoId",o.productoId(),"retenido",o.retenido());if(o.accionPendiente()==null&&!o.historica()){if(o.congelable()) permitidas.add(Accion.OPERACION_CONGELADA);if(o.reembolsable()) permitidas.add(Accion.OPERACION_REEMBOLSADA);}}
  }catch(RuntimeException e){objetivo=Map.of("error","No se pudo consultar el objetivo. Reintenta antes de actuar");permitidas=new ArrayList<>(List.of(Accion.SIN_ACCION));}
  var todos=reportes.findAll();return new ContextoReporte(service.vista(r,a),objetivo,precio,todos.stream().filter(x->x.getReportanteId().equals(r.getReportanteId())&&x.getEstado()==Estado.RECHAZADO).count(),todos.stream().filter(x->!x.getId().equals(id)&&x.getTipoObjetivo()==r.getTipoObjetivo()&&x.getObjetivoId().equals(r.getObjetivoId())).limit(50).map(x->service.vista(x,a)).toList(),todos.stream().filter(x->!x.getId().equals(id)&&x.getDenunciadoId().equals(r.getDenunciadoId())).limit(50).map(x->service.vista(x,a)).toList(),registro.historial("REPORTE",id),!abierto(r.getEstado())||r.isAccionPendiente()?List.of():permitidas);
 }
}
